function summarize(c){const compact=String(c.description||'').trim().replace(/\s+/g,' ');const snippet=compact.length>180?compact.slice(0,177)+'…':compact;return `${c.title} is a ${c.domain.toLowerCase()} challenge reported in ${c.district||'Jharkhand'}. ${snippet}`}
