function buildInnovationMemoryRecord(c){return {version:'v22-memory-1',challengeId:c.id,challengeDNA:c.challengeDNA||buildChallengeDNA(c),context:{district:c.district,location:c.locationText,population:c.affectedPopulation,severity:c.severity,urgency:c.urgency},rootCauses:c.rootCauseRecords||buildRootCauseRecords(c),solution:c.proposal||null,team:{members:c.teamMembers||[],facultyMentor:c.facultyMentor||'',crossUniversity:c.crossUniversity||[]},universityAssignment:c.universityAssignment||null,industryAssignment:c.industryAssignment||null,cost:{approved:num(c.approvedBudget||c.proposal?.estimatedCost),spent:num(c.budgetSpent)},timelineWeeks:num(c.proposal?.timelineWeeks),prototype:{status:c.prototypeStatus||'',note:c.prototypeNote||''},pilot:c.pilotNote||'',outcome:c.outcome||'',impact:c.impact||null,evidence:[...(c.evidence||[]),...((c.impact||{}).evidenceFiles||[])],failureReasons:c.outcome==='failed'||c.outcome==='partial'?(c.riskRegister||[]):[],lessons:c.lessons||'',reuseConditions:(c.decisionReview?.note? [c.decisionReview.note]:[]),reuseLimitations:(c.transferabilityAnalysis?.incompatibilities||[]),storedAt:now(),demonstrationData:!!c.isDemonstrationData}}
function ensureIntelligenceRecord(c){if(!c||!c.id)return c;const x={...c};x.rootCauses=x.rootCauses?.length?x.rootCauses:rootCauses(x);x.challengeDNA=x.challengeDNA||buildChallengeDNA(x);x.rootCauseRecords=x.rootCauseRecords||buildRootCauseRecords(x);x.problemFamily=x.problemFamily||buildProblemFamily(x,x.duplicateOf?{id:x.duplicateOf}:null);x.transferabilityAnalysis=x.transferabilityAnalysis||transferDecision(x);if(x.status==='closed'&&!x.innovationMemoryRecord)x.innovationMemoryRecord=buildInnovationMemoryRecord(x);x.intelligenceProvenance=x.intelligenceProvenance||{generatedAt:now(),logicVersion:'v22-local-intelligence-1',classifierSource:x.classificationSource||'historical-record',humanReviewRequired:true};return x}
function duplicateFor(c,ignoreId){let best=null;for(const x of state.challenges){if(x.id===ignoreId)continue;const sem=similarity(`${c.title} ${c.description}`,`${x.title} ${x.description}`);const total=Math.min(1,sem*.7+(c.domain===x.domain?.15:0)+(c.district===x.district?.15:0));if(!best||total>best.score)best={id:x.id,score:total,title:x.title}}return best&&best.score>=.58?best:null}
function transferDecision(c){const completed=state.challenges.filter(x=>x.status==='closed'&&x.proposal&&x.id!==c.id);if(!completed.length)return {decision:'INVENT',score:0,related:null,reason:'Innovation Memory has no completed project with enough evidence yet.',factors:{problemSimilarity:'No prior evidence',geography:'Unknown',population:'Unknown',infrastructure:'Unknown',connectivity:'Unknown',cost:'Unknown',maintenance:'Unknown',localSkills:'Unknown',stakeholders:'Unknown',operationalConstraints:'Unknown'},incompatibilities:['No sufficiently comparable completed project is stored.'],assumptions:['Historical evidence is currently insufficient.'],confidence:.35,adaptations:['Define local baseline, constraints and success criteria before designing a new solution.']};let best=null,bs=0;for(const x of completed){const sem=similarity(`${c.title} ${c.description}`,`${x.title} ${x.description}`),score=Math.min(1,sem*.5+(c.domain===x.domain?.25:0)+(c.district===x.district?.1:0)+(x.outcome==='successful'?.15:x.outcome==='partial'?.07:0));if(score>bs){bs=score;best=x}}const pct=Math.round(bs*100),decision=pct>=75?'REUSE':pct>=45?'ADAPT':'INVENT',adapt=[];if(best){if(best.district!==c.district)adapt.push('Revalidate geography, field access and stakeholder conditions in the new district.');if((best.locationText||'')!==(c.locationText||''))adapt.push('Recheck infrastructure, connectivity, operating and maintenance constraints.');if(best.affectedPopulation&&c.affectedPopulation&&Math.max(best.affectedPopulation,c.affectedPopulation)/Math.max(1,Math.min(best.affectedPopulation,c.affectedPopulation))>1.8)adapt.push('Resize capacity, cost and operating model for the different beneficiary scale.');if(best.outcome==='partial'||best.outcome==='failed')adapt.push('Resolve the previous project’s recorded failure reasons before reuse.')}if(!adapt.length&&decision==='REUSE')adapt.push('Retain the verified operating model, then run a short local validation before full deployment.');if(decision==='INVENT')adapt.push('Use prior records only as evidence; design and validate a new approach for this context.');const factors={problemSimilarity:`${Math.round(similarity(`${c.title} ${c.description}`,`${best?.title||''} ${best?.description||''}`)*100)}%`,geography:best?.district===c.district?'High':'Medium / revalidate',population:best?.affectedPopulation&&c.affectedPopulation?(Math.max(best.affectedPopulation,c.affectedPopulation)/Math.max(1,Math.min(best.affectedPopulation,c.affectedPopulation))<=1.8?'Compatible':'Different scale'):'Unknown',infrastructure:(best?.locationText||'')===(c.locationText||'')?'Similar recorded context':'Requires field check',connectivity:'Requires explicit field confirmation',cost:best?.proposal?.estimatedCost&&c.proposal?.estimatedCost?'Comparable project cost available':'Not enough cost evidence',maintenance:['Water Resources','Sanitation','Energy','Urban Development'].includes(c.domain)?'Maintenance-sensitive':'Standard review',localSkills:(best?.requiredSkills||[]).some(x=>(c.requiredSkills||[]).includes(x))?'Some overlap':'Needs confirmation',stakeholders:best?.district===c.district?'Potential local overlap':'Different local stakeholders',operationalConstraints:'Review prior lessons and local constraints'};const incompatibilities=adapt.slice();return {decision,score:pct,related:best,reason:decision==='REUSE'?'A strong contextual match exists.':decision==='ADAPT'?'A related solution exists, but local modifications are recommended.':'Available evidence is not strong enough for direct transfer.',factors,incompatibilities,assumptions:['Transferability is a transparent prototype heuristic, not a statistically validated prediction.'],confidence:Math.min(.9,.45+bs*.45),adaptations:adapt}}
function impactScore(i={}){let s=0;if(i.metricName&&Number.isFinite(Number(i.baselineValue)))s+=25;if(Number(i.postValue)!==Number(i.baselineValue))s+=25;if(String(i.evidenceNote||'').trim().length>=10)s+=12;if((i.evidenceFiles||[]).length)s+=8;s+=Math.round(clamp(num(i.communityScore),0,5)/5*15);if(i.governmentVerified)s+=15;return Math.min(100,s)}
function notifyRolesFor(action,c){if(action==='submit'){notify('government','New challenge submitted',`${c.title} is waiting for review.`)}if(action==='validate'){notify('citizen','Challenge validated',`${c.title} has passed government review.`);notify('university','New validated challenge',`${c.title} is available for capability matching.`);notify('industry','New societal opportunity',`${c.title} is available for collaboration.`)}if(action==='assign'){notify('university','Challenge routed',`${c.title} has been matched to a university.`);notify('industry','Partnership request',`${c.title} has been routed for industry support.`)}if(action==='pilot'){notify('government','Pilot ready for monitoring',`${c.title} has entered pilot.`);notify('citizen','Solution entered pilot',`${c.title} has entered pilot.`)}if(action==='close'){notify('citizen','Impact verified',`${c.title} has been closed with a verified outcome.`)}}
function relatedFamily(c){return state.challenges.filter(x=>x.id!==c.id&&x.domain===c.domain&&(x.district===c.district||similarity(`${c.title} ${c.description}`,`${x.title} ${x.description}`)>=.22)).slice(0,8)}
function requiredSkills(c){return SKILLS[c.domain]||['Domain Expert','Software Engineering','Field Research']}
function suggestTeamComposition(c,d=currentProfileData()){
 const need=requiredSkills(c),students=d.students||[],faculty=d.faculty||[]
 const scoreLine=(line,skill)=>{const a=String(line).toLowerCase(),b=String(skill).toLowerCase();let score=0;b.split(/\s+/).filter(x=>x.length>3).forEach(x=>{if(a.includes(x))score++});return score}
 const picked=[],used=new Set()
 for(const skill of need){let best=null,score=0;for(const person of students){if(used.has(person))continue;const n=scoreLine(person,skill);if(n>score){best=person;score=n}}if(best){picked.push(best);used.add(best)}}
 for(const person of students){if(picked.length>=Math.min(5,Math.max(3,need.length+1)))break;if(!used.has(person)){picked.push(person);used.add(person)}}
 let mentor='';let mentorScore=-1;for(const f of faculty){const n=need.reduce((a,x)=>a+scoreLine(f,x),0);if(n>mentorScore){mentor=f;mentorScore=n}}
 return {members:picked.slice(0,5),mentor:mentor||faculty[0]||'',skills:need,explanation:`Suggested from ${students.length} student/researcher profile${students.length===1?'':'s'}, ${faculty.length} faculty record${faculty.length===1?'':'s'} and ${need.length} required skill${need.length===1?'':'s'}. Human review remains required.`}
}
function universityMatches(c){const need=new Set(requiredSkills(c).map(x=>x.toLowerCase()));return state.profiles.filter(p=>p.role==='university').map(p=>{const d=state.profileData[p.id]||{},pool=[...(d.expertise||[]),...(d.departments||[]),...(d.skills||[])].map(x=>String(x).toLowerCase());let overlap=0;need.forEach(n=>pool.some(x=>x.includes(n)||n.includes(x))&&overlap++);const domainHit=pool.some(x=>x.includes(c.domain.toLowerCase().split(' ')[0]));const availability=d.available===false?0:15;const score=Math.min(100,20+overlap*20+(domainHit?25:0)+availability+(d.labs?.length?10:0));return {profile:p,data:d,score,reasons:[overlap?`${overlap} required skill match${overlap>1?'es':''}`:'No declared required-skill overlap',domainHit?'Domain capability declared':'Domain capability not declared',d.labs?.length?'Lab/incubator capacity recorded':'No lab capacity recorded']}}).sort((a,b)=>b.score-a.score)}
function industryMatches(c){const need=new Set(requiredSkills(c).map(x=>x.toLowerCase()));return state.profiles.filter(p=>p.role==='industry').map(p=>{const d=state.profileData[p.id]||{},pool=[...(d.capabilities||[]),...(d.technologies||[]),...(d.mentorSkills||[])].map(x=>String(x).toLowerCase());let overlap=0;need.forEach(n=>pool.some(x=>x.includes(n)||n.includes(x))&&overlap++);const domainHit=pool.some(x=>x.includes(c.domain.toLowerCase().split(' ')[0]));const mentorReady=d.mentorAvailable!==false&&(d.mentorSkills||[]).length>0;const score=Math.min(100,15+overlap*18+(domainHit?22:0)+(num(d.fundingCapacity)>0?12:0)+(d.prototypeResources?.length?9:0)+(d.pilotSites?.length?9:0)+(mentorReady?6:0));return {profile:p,data:d,score,reasons:[overlap?`${overlap} capability match${overlap>1?'es':''}`:'No declared capability overlap',mentorReady?'Mentor availability recorded':'Mentor availability not confirmed',num(d.fundingCapacity)>0?'Funding capacity recorded':'No funding capacity recorded',d.pilotSites?.length?'Pilot-site capacity recorded':'No pilot site recorded']}}).sort((a,b)=>b.score-a.score)}
function officialUniversityMatches(c){
 const need=requiredSkills(c).map(x=>x.toLowerCase()),domainKey=c.domain.toLowerCase().split(' ')[0]
 return (referenceData.institutions||[]).map((inst,index)=>{const pool=(inst.inferredCapabilities||[]).map(x=>String(x).toLowerCase());let overlap=0;need.forEach(n=>pool.some(x=>x.includes(n)||n.includes(x))&&overlap++);const domainHit=pool.some(x=>x.includes(domainKey)||domainKey.includes(x.split(' ')[0]));const districtHit=String(inst.district||'').toLowerCase()===String(c.district||'').toLowerCase();const score=Math.min(92,28+overlap*18+(domainHit?20:0)+(districtHit?12:0));return {index,inst,score,reasons:[`${inst.type||'Institution'} · official directory reference`,overlap?`${overlap} inferred capability overlap${overlap>1?'s':''}`:'Capability must be confirmed by institution',districtHit?'Same district context':'Cross-district candidate']}}).sort((a,b)=>b.score-a.score)
}

function currentProfileData(){return state.profileData[session.id]||{}}
function updateProfileData(patch){state.profileData[session.id]={...currentProfileData(),...patch};activity(session.name,'Updated capability/profile information',session.id);saveState('profile');render()}
function setChallenge(id,patch,action){const i=state.challenges.findIndex(c=>c.id===id);if(i<0)return;state.challenges[i]={...state.challenges[i],...patch,updatedAt:now()};if(action)activity(session.name,action,id);saveState(action||'challenge-update')}
function challengeById(id){return state.challenges.find(c=>c.id===id)}
function myChallenges(){return state.challenges.filter(c=>c.createdBy===session.id)}
function availableForUni(){return state.challenges.filter(c=>['validated','assigned','in-progress','pilot'].includes(c.status)).filter(c=>!(c.universityDeclines||[]).includes(session.id)).filter(c=>!c.universityAssignment||c.universityAssignment===session.id)}
function availableForIndustry(){return state.challenges.filter(c=>['validated','assigned','in-progress','pilot'].includes(c.status)).filter(c=>!c.industryAssignment||c.industryAssignment===session.id)}
function selectedOrFirst(filter=()=>true){return challengeById(ui.selectedChallenge)||state.challenges.find(filter)||null}

function pageHead(kicker,title,desc,actions=''){return `<div class="page-head xp-page-head"><div><span class="smallcaps">${kicker}</span><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`}
function metrics(items){return `<div class="grid four">${items.map(x=>`<div class="metric-card"><div class="label">${icon(x.icon||'activity','sm')} ${x.label}</div><b>${esc(x.value)}</b><small>${x.sub||''}</small></div>`).join('')}</div>`}
function emptyState(iconName,title,copy,button=''){return `<div class="empty"><div class="empty-icon">${icon(iconName,'lg')}</div><h3>${title}</h3><p>${copy}</p>${button}</div>`}
function challengeRow(c,actionLabel='Open'){return `<div class="list-row"><div><h4>${esc(c.title)}</h4><p>${esc(c.aiSummary||c.description)}</p><div class="meta"><span class="badge ${c.status}">${esc(c.status)}</span><span class="tag">${esc(c.domain)}</span><span class="tag">${icon('map','sm')} ${esc(c.district||'Location pending')}</span><span class="tag ${c.priorityScore>=75?'bad':c.priorityScore>=50?'warn':'good'}">Priority ${c.priorityScore||0}</span></div></div><button class="btn sm" data-open-challenge="${c.id}">${actionLabel} ${icon('chevron','sm')}</button></div>`}
function journeyHtml(c){const labels=[['Report','Ground truth'],['Understand','Challenge DNA'],['Decide','Reuse / Adapt / Invent'],['Collaborate','HEI + Industry'],['Verify','Impact evidence'],['Remember','Innovation memory']],stage=statusStage(c.status);return `<div class="journey">${labels.map((x,i)=>`<div class="journey-step ${i<stage?'done':i===stage?'active':''}"><span>${i<stage?icon('check','sm'):String(i+1).padStart(2,'0')}</span><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div>`}
function roleHero(title,copy,stats,journey=true){return `<section class="hero xp-role-hero"><div class="xp-role-hero-main"><span class="smallcaps">${ROLE_META[session.role].verb} workspace</span><h2>${title}</h2><p>${copy}</p>${journey?`<div class="xp-workflow-rail">${['Report','Understand','Decide','Collaborate','Verify','Remember'].map((x,i)=>`<span class="${i===0&&session.role==='citizen'?'current':''}"><b>${String(i+1).padStart(2,'0')}</b>${x}</span>${i<5?'<i></i>':''}`).join('')}</div>`:''}</div><div class="xp-role-stats">${stats.map(x=>`<div><small>${x.label}</small><b>${x.value}</b><span>${x.sub||''}</span></div>`).join('')}</div></section>`}

function renderPage(){if(ui.page==='notifications')return renderNotifications();if(ui.page==='profile')return renderProfile();if(session.role==='citizen')return renderCitizen();if(session.role==='university')return renderUniversity();if(session.role==='industry')return renderIndustry();return renderGovernment()}

function renderCitizen(){
 const mine=myChallenges();
 if(ui.page==='submit')return renderCitizenSubmit();
 if(ui.page==='challenges')return renderCitizenChallenges();
 if(ui.page==='community')return renderCommunity();
 const active=mine.filter(c=>!['closed','rejected'].includes(c.status)); const closed=mine.filter(c=>c.status==='closed');
 return `${pageHead('Citizen / Community','Your problem should not disappear after submission.','Jharkhandi keeps the complete decision trail visible — from ground truth to verified impact.',`<button class="btn primary" data-page-jump="submit">${icon('plus','sm')} Report a challenge</button>`)}
 ${roleHero('From ground truth to a visible outcome.','Submit evidence once, then follow how government, universities and industry understand, decide, build and verify the solution.',[{label:'My challenges',value:mine.length,sub:'created by this profile'},{label:'Active journey',value:active.length,sub:'not yet closed'},{label:'Verified outcomes',value:closed.filter(c=>c.impact?.governmentVerified).length,sub:'government verified'},{label:'Community supports',value:mine.reduce((n,c)=>n+num(c.communityValidations),0),sub:'on your reports'}])}
 <div class="grid asym">
  <section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('activity')}</div><div><h3>My challenge journey</h3><p>Every status below comes from an actual workflow action in this deployment.</p></div></div></div>${mine.length?`<div class="list">${mine.slice(0,5).map(c=>challengeRow(c,'Track')).join('')}</div>`:emptyState('target','No challenge reported yet','Start with one real community problem. The system will generate structured context, priority and an explainable decision path.',`<button class="btn primary" data-page-jump="submit">${icon('plus','sm')} Report first challenge</button>`)}</section>
  <section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('shield')}</div><div><h3>What happens after you report?</h3><p>A transparent, reviewable sequence — not a black box.</p></div></div></div><div class="timeline">
   ${[['Government review','Evidence and duplicate checks'],['Challenge intelligence','DNA, root cause, family and priority'],['Capability routing','University and industry matching'],['Prototype & pilot','Milestones, testing and field deployment'],['Impact verification','Baseline, post metric, community evidence'],['Innovation memory','Outcome becomes reusable evidence']].map(x=>`<div class="timeline-item"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}
  </div></section>
 </div>`
}

function renderCitizenSubmit(){
 const draft=JSON.parse(localStorage.getItem(`jh_draft_${session.id}`)||'{}')
 const trainingCount=referenceData.model?.trainingExamples||referenceData.model?.baseExamples||0
 return `${pageHead('Citizen / Community','Report a challenge','Capture the problem once. Location, evidence and operating context become reusable inputs for every later decision.',`<button class="btn" id="load-draft">${icon('clock','sm')} Restore draft</button>`)}
 <div class="xp-form-progress"><span class="active"><b>01</b> Problem</span><i></i><span><b>02</b> Place</span><i></i><span><b>03</b> Evidence</span><i></i><span><b>04</b> Intelligence</span></div>
 <div class="grid asym xp-submit-layout"><form class="card xp-intake-card" id="challenge-form">
 <div class="xp-form-section"><div class="xp-form-section-head"><span>01</span><div><h3>Describe the societal problem</h3><p>Describe the observed issue. Root causes remain separate, reviewable hypotheses.</p></div></div><div class="form-grid"><div class="field span-2"><label>Challenge title <span>Required</span></label><input name="title" required value="${esc(draft.title||'')}" placeholder="e.g. Irregular drinking-water supply in three villages"/></div><div class="field span-2"><label>What is happening? <span>Required</span></label><textarea name="description" required placeholder="Describe who is affected, since when, frequency, current service conditions and any earlier attempts.">${esc(draft.description||'')}</textarea></div><div class="field"><label>Domain</label><select name="domain"><option>Auto-detect</option>${DOMAINS.map(d=>`<option ${draft.domain===d?'selected':''}>${d}</option>`).join('')}</select><div class="helper">Auto-detect uses the trained local classifier + controlled taxonomy. Government can correct it.</div></div><div class="field"><label>Challenge language</label><select name="submissionLanguage">${LANGUAGE_OPTIONS.map(x=>`<option value="${esc(x.value)}" ${(draft.submissionLanguage||currentLanguage().value||'English')===x.value?'selected':''}>${esc(x.label)}</option>`).join('')}</select><div class="helper">Citizens can write in any listed Jharkhand language. The original Unicode report is preserved. Community-draft language packs keep technical terms bilingual and low-confidence classification remains reviewable by Government.</div></div><div class="field"><label>Affected population</label><input type="number" min="0" name="affectedPopulation" value="${esc(draft.affectedPopulation||'')}" placeholder="Approx. people affected"/></div><div class="field"><label>Severity</label><select name="severity">${[1,2,3,4,5].map(n=>`<option ${num(draft.severity||3)===n?'selected':''} value="${n}">${n} — ${['Low','Moderate','Significant','High','Critical'][n-1]}</option>`).join('')}</select></div><div class="field"><label>Urgency</label><select name="urgency">${[1,2,3,4,5].map(n=>`<option ${num(draft.urgency||3)===n?'selected':''} value="${n}">${n} — ${['Can wait','Soon','Important','Urgent','Immediate'][n-1]}</option>`).join('')}</select></div></div></div>
 <div class="xp-form-section"><div class="xp-form-section-head"><span>02</span><div><h3>Add place and operating context</h3><p>Context transfer later compares geography, access, infrastructure and maintenance conditions — not text alone.</p></div></div><div class="form-grid"><div class="field"><label>District <span>Required</span></label><input name="district" required value="${esc(draft.district||session.district||'')}" placeholder="District in Jharkhand"/></div><div class="field"><label>Block / municipality</label><input name="block" value="${esc(draft.block||'')}" placeholder="Block or municipality"/></div><div class="field"><label>Village / ward</label><input name="village" value="${esc(draft.village||'')}" placeholder="Village or ward"/></div><div class="field"><label>Existing attempts / constraints</label><input name="locationText" value="${esc(draft.locationText||'')}" placeholder="Connectivity, access, maintenance, earlier attempts…"/></div><div class="field span-2"><label>GPS & live context</label><div class="xp-inline-input"><input id="gps-value" name="gps" readonly value="${draft.latitude?`${draft.latitude}, ${draft.longitude}`:''}" placeholder="Capture current location if relevant"/><button type="button" class="btn" id="gps-btn">${icon('map','sm')} Use current location</button></div><div class="helper" id="gps-help">Location permission is requested only when you click the button.</div><div id="live-context-preview" class="live-context-preview"></div></div></div></div>
 <div class="xp-form-section"><div class="xp-form-section-head"><span>03</span><div><h3>Attach field evidence</h3><p>Evidence is persisted on the local server and remains linked to the challenge record.</p></div></div><div class="field"><div class="file-drop xp-file-drop"><input id="evidence-input" name="evidence" type="file" multiple accept="image/*,video/mp4,video/webm,.pdf,.doc,.docx,.txt"/><label for="evidence-input">${icon('upload','lg')}<b>Drop or choose evidence files</b><small>Images, MP4/WebM, PDF, DOC/DOCX or TXT · up to 8 files · max 10 MB each</small></label><div class="file-list" id="evidence-preview"></div></div></div><label class="check-row"><input type="checkbox" name="anonymous" ${draft.anonymous?'checked':''}/><span>Hide my identity from public/community views. The audit record still keeps the creator ID.</span></label></div>
 <div class="xp-form-submit"><div><b>Ready for Challenge Intelligence</b><small>Submission creates trained classification, explainable priority, duplicate signal, Challenge DNA, root-cause hypotheses and required skills.</small></div><div><button type="button" class="btn" id="save-draft">Save draft</button><button class="btn primary" type="submit">${icon('spark','sm')} Submit & analyse</button></div></div></form>
 <aside class="xp-intake-aside"><div class="xp-aside-sticky"><span class="xp-overline">LIVE INTELLIGENCE</span><h3>Evidence in. Decision context out.</h3><p>The classifier is seed-trained on public SIH 2026 problem statements, blended with a controlled taxonomy, and can learn from reviewer corrections.</p><div class="model-trust"><span>${icon('brain','sm')}</span><div><small>TRAINED CLASSIFIER</small><b>${trainingCount||'—'} examples available locally</b></div></div><div class="xp-derived-list">${[['01','Classification','Domain + sub-domain + top alternatives'],['02','Priority','Severity + urgency + population'],['03','Duplicate signal','Text + domain + district context'],['04','Challenge DNA','Structured context and constraints'],['05','Problem Family','Related reports grouped together'],['06','Capability need','Skills used for university and industry matching']].map(x=>`<div><span>${x[0]}</span><section><b>${x[1]}</b><small>${x[2]}</small></section></div>`).join('')}</div></div></aside></div>`
}
function renderCitizenChallenges(){const mine=myChallenges();return `${pageHead('Challenge tracking','My challenges','Open the complete decision trail for every problem you have reported.')}${mine.length?`<div class="list">${mine.map(c=>challengeRow(c,'Open journey')).join('')}</div>`:emptyState('target','Nothing to track yet','Report a challenge first; it will appear here with its live status and evidence trail.',`<button class="btn primary" data-page-jump="submit">Report challenge</button>`)}`}
function renderCommunity(){const list=state.challenges.filter(c=>!['rejected'].includes(c.status));return `${pageHead('Community validation','Confirm what communities are actually experiencing.','Support an existing challenge once per local profile. Community validation becomes one input to impact integrity — not a popularity vote.')}${list.length?`<div class="grid two">${list.map(c=>`<div class="challenge-card"><div class="challenge-card-top"><div><h3>${esc(c.title)}</h3><p>${esc(c.aiSummary||c.description)}</p></div><span class="badge ${c.status}">${c.status}</span></div><div class="challenge-card-body"><div class="challenge-meta"><div><small>District</small><b>${esc(c.district)}</b></div><div><small>Domain</small><b>${esc(c.domain)}</b></div><div><small>Supports</small><b>${num(c.communityValidations)}</b></div><div><small>Priority</small><b>${num(c.priorityScore)}</b></div></div><div style="display:flex;justify-content:flex-end;gap:7px;margin-top:12px"><button class="btn sm" data-open-challenge="${c.id}">View evidence</button><button class="btn primary sm" data-community="${c.id}" ${c.communityValidatorIds?.includes(session.id)?'disabled':''}>${icon('check','sm')} ${c.communityValidatorIds?.includes(session.id)?'Supported':'Confirm this challenge'}</button></div></div></div>`).join('')}</div>`:emptyState('users','No community challenge is available yet','Once a citizen submits a challenge, the community can review its context and confirm that the issue is real.')}`}

function renderUniversity(){
 if(ui.page==='matched')return renderUniversityMatched();
 if(ui.page==='teams')return renderUniversityTeams();
 if(ui.page==='proposals')return renderUniversityProposals();
 if(ui.page==='projects')return renderUniversityProjects();
 if(ui.page==='ip')return renderIPRegistry('university');
 if(ui.page==='capability')return renderUniversityCapability();
 const pdata=currentProfileData(),matched=availableForUni(),assigned=state.challenges.filter(c=>c.universityAssignment===session.id),active=assigned.filter(c=>!['closed','rejected'].includes(c.status));
 return `${pageHead('University / HEI','A solution workspace built around real societal demand.','Capability comes first. Jharkhandi explains why a challenge matches your institution before teams spend time on it.',`<button class="btn primary" data-page-jump="matched">${icon('target','sm')} View matched challenges</button>`)}
 ${roleHero('Turn validated needs into testable solutions.','Build multidisciplinary teams, assign faculty mentors, submit proposals, run a pre-mortem and move through prototype, testing and pilot with evidence.',[{label:'Matched',value:matched.length,sub:'eligible challenges'},{label:'Assigned',value:assigned.length,sub:'to this institution'},{label:'Active projects',value:active.filter(c=>c.proposal).length,sub:'with a proposal'},{label:'Capability profile',value:profileCompleteness(pdata,'university')+'%',sub:'complete'}])}
 <div class="grid asym"><section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('target')}</div><div><h3>Matched work</h3><p>Matches are based only on capability data entered by this institution.</p></div></div></div>${matched.length?`<div class="list">${matched.slice(0,5).map(c=>challengeRow(c,c.universityAssignment===session.id?'Open project':'Review match')).join('')}</div>`:emptyState('university','No matched challenge yet','Complete your capability profile, or wait for government to validate a challenge.',`<button class="btn" data-page-jump="capability">Complete capability profile</button>`)}</section>
 <section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('brain')}</div><div><h3>Institution readiness</h3><p>Matching is explainable, not a hidden ranking.</p></div></div></div>${capabilitySummary(pdata,'university')}</section></div>`
}
function profileCompleteness(d,role){const fields=role==='university'?['departments','expertise','labs','skills','faculty','students']:['capabilities','technologies','mentorSkills','prototypeResources','pilotSites','fundingCapacity'];return Math.round(fields.filter(k=>Array.isArray(d[k])?d[k].length:d[k]).length/fields.length*100)}
function capabilitySummary(d,role){if(role==='university'){const items=[['Departments',(d.departments||[]).length],['Expertise',(d.expertise||[]).length],['Labs / incubators',(d.labs||[]).length],['Student skills',(d.skills||[]).length],['Faculty',(d.faculty||[]).length],['Previous projects',(d.previousProjects||[]).length]];return `<div class="grid two">${items.map(x=>`<div class="dna-item"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div><button class="btn" style="margin-top:12px" data-page-jump="capability">${icon('edit','sm')} Edit institution capability</button>`}const items=[['Capabilities',(d.capabilities||[]).length],['Technologies',(d.technologies||[]).length],['Mentor skills',(d.mentorSkills||[]).length],['Prototype resources',(d.prototypeResources||[]).length],['Pilot sites',(d.pilotSites||[]).length],['Funding capacity',d.fundingCapacity?`₹${Number(d.fundingCapacity).toLocaleString('en-IN')}`:'Not set']];return `<div class="grid two">${items.map(x=>`<div class="dna-item"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div><button class="btn" style="margin-top:12px" data-page-jump="capability">${icon('edit','sm')} Edit partner capability</button>`}
function renderUniversityMatched(){const items=availableForUni();return `${pageHead('Discover','Matched challenges','Each card explains the context and lets the institution accept responsibility explicitly.')}${items.length?`<div class="list">${items.map(c=>{const match=universityMatches(c).find(x=>x.profile.id===session.id);return `<div class="list-row"><div><h4>${esc(c.title)}</h4><p>${esc(c.aiSummary)}</p><div class="meta"><span class="badge ${c.status}">${c.status}</span><span class="tag">${esc(c.domain)}</span><span class="tag ${match?.score>=70?'good':match?.score>=45?'warn':''}">Capability match ${match?.score||20}%</span>${(match?.reasons||[]).slice(0,2).map(r=>`<span class="tag">${esc(r)}</span>`).join('')}</div></div><div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end"><button class="btn sm" data-open-challenge="${c.id}">Inspect</button>${!c.universityAssignment?`<button class="btn sm" data-uni-decline="${c.id}">Not a fit</button><button class="btn primary sm" data-uni-accept="${c.id}">Accept challenge</button>`:c.universityAssignment===session.id?`<span class="tag good">Assigned to you</span>`:''}</div></div>`}).join('')}</div>`:emptyState('target','No challenge is currently matched','A validated government challenge will appear here. Complete your capability profile to improve explainable matching.')}`}
function renderUniversityTeams(){const assigned=state.challenges.filter(c=>c.universityAssignment===session.id),d=currentProfileData();return `${pageHead('Build','Teams & mentors','Create multidisciplinary teams, assign faculty mentors and record cross-university participation.')}${assigned.length?assigned.map(c=>{const sug=suggestTeamComposition(c,d);return `<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.id)} • ${esc(c.domain)}</p></div><button class="btn sm" data-open-challenge="${c.id}">Challenge context</button></div><div class="ai-assist"><span>${icon('spark','sm')}</span><div><small>AI-ASSISTED TEAM COMPOSITION</small><b>${sug.members.length||'No'} candidate member${sug.members.length===1?'':'s'} • ${sug.skills.length} required skills</b><p>${esc(sug.explanation)}</p></div><button type="button" class="btn sm" data-team-suggest="${c.id}" ${!sug.members.length&&!sug.mentor?'disabled':''}>Use suggestion</button></div><div class="team-suggestion-grid"><div><small>Suggested members</small><b>${esc(sug.members.join(' • ')||'Add student/researcher profiles in Capability first')}</b></div><div><small>Suggested mentor</small><b>${esc(sug.mentor||'Add faculty expertise in Capability first')}</b></div><div><small>Required skill coverage</small><b>${esc(sug.skills.join(' • '))}</b></div></div><form class="team-form" data-team-form="${c.id}"><div class="form-grid"><div class="field"><label>Student / researcher team members</label><textarea name="teamMembers" placeholder="One member per line">${esc((c.teamMembers||[]).join('\n'))}</textarea></div><div class="field"><label>Faculty mentor</label><input name="facultyMentor" value="${esc(c.facultyMentor||'')}" placeholder="Faculty mentor name"/><div class="helper">AI can suggest a mentor, but the university confirms the assignment.</div></div><div class="field"><label>Cross-university collaborators</label><textarea name="crossUniversity" placeholder="Institution / collaborator per line">${esc((c.crossUniversity||[]).join('\n'))}</textarea></div><div class="field"><label>Team skill coverage</label><textarea name="teamSkills" placeholder="Skills covered by this team">${esc((c.teamSkills||[]).join('\n'))}</textarea></div></div><div class="form-actions"><button class="btn primary">Save team & mentor</button></div></form></section>`}).join(''):emptyState('users','No assigned challenge yet','Accept a matched challenge first. Team formation becomes available once responsibility is clear.',`<button class="btn" data-page-jump="matched">Open matched challenges</button>`)}`}

function renderUniversityProposals(){const items=state.challenges.filter(c=>c.universityAssignment===session.id);return `${pageHead('Build','Solution proposals','A proposal includes approach, cost, timeline, success criteria and an automatic pre-mortem before government approval.')}${items.length?items.map(c=>`<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${c.proposal?'Proposal submitted • '+fmtDate(c.proposal.submittedAt):'No proposal submitted yet'}</p></div><span class="badge ${c.proposalReview==='approved'?'validated':c.proposalReview==='changes-requested'?'under-review':c.status}">${c.proposalReview||'draft'}</span></div><form data-proposal-form="${c.id}"><div class="form-grid"><div class="field span-2"><label>Solution summary</label><input name="summary" required value="${esc(c.proposal?.summary||'')}" placeholder="One-line solution hypothesis"/></div><div class="field span-2"><label>Approach</label><textarea name="approach" required placeholder="How will the team solve, prototype and test this problem?">${esc(c.proposal?.approach||'')}</textarea></div><div class="field"><label>Estimated cost (₹)</label><input type="number" min="0" name="estimatedCost" value="${num(c.proposal?.estimatedCost)||''}"/></div><div class="field"><label>Timeline (weeks)</label><input type="number" min="1" name="timelineWeeks" value="${num(c.proposal?.timelineWeeks)||''}"/></div><div class="field span-2"><label>Success criteria</label><textarea name="successCriteria" placeholder="One measurable success criterion per line">${esc((c.successCriteria||[]).join('\n'))}</textarea></div></div><div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="btn primary">${icon('shield','sm')} Submit proposal & run pre-mortem</button></div></form>${c.proposal?.preMortem?.length?`<div class="section"><div class="section-title"><div><h3>AI project pre-mortem</h3><p>Reviewable failure hypotheses generated before implementation.</p></div></div>${c.proposal.preMortem.map(x=>`<div class="premortem-row"><header><b>${esc(x.title)}</b><span class="tag ${x.probability==='High'?'bad':'warn'}">${x.probability}</span></header><p><b>Mitigation:</b> ${esc(x.mitigation)}</p></div>`).join('')}</div>`:''}</section>`).join(''):emptyState('file','No challenge is ready for a proposal','Accept a challenge first, then form the team and submit a solution proposal.')}`}
function renderUniversityProjects(){const items=state.challenges.filter(c=>c.universityAssignment===session.id&&c.proposal);return `${pageHead('Deliver','Prototype, testing & pilot','Manage milestones, tasks, deliverables, budget, risk, testing, pilot, deployment and lessons learned.')}${items.length?items.map(c=>renderProjectWorkspace(c,'university')).join(''):emptyState('layers','No active project yet','A project workspace appears after the university submits a proposal.',`<button class="btn" data-page-jump="proposals">Open proposals</button>`)}`}
function renderUniversityCapability(){const d=currentProfileData();return `${pageHead('Institution','Labs & capability profile','This is the evidence Jharkhandi uses for university routing. No capability is assumed unless you enter it.')}
 <form class="card" id="university-capability-form"><div class="form-grid"><div class="field"><label>Departments</label><textarea name="departments" placeholder="One per line">${esc((d.departments||[]).join('\n'))}</textarea></div><div class="field"><label>Research expertise</label><textarea name="expertise" placeholder="One capability per line">${esc((d.expertise||[]).join('\n'))}</textarea></div><div class="field"><label>Labs & incubators</label><textarea name="labs" placeholder="Lab / incubator per line">${esc((d.labs||[]).join('\n'))}</textarea></div><div class="field"><label>Student skill matrix</label><textarea name="skills" placeholder="Skill per line">${esc((d.skills||[]).join('\n'))}</textarea></div><div class="field"><label>Faculty expertise</label><textarea name="faculty" placeholder="Name — expertise">${esc((d.faculty||[]).join('\n'))}</textarea></div><div class="field"><label>Student / researcher profiles</label><textarea name="students" placeholder="Name — skills / interests">${esc((d.students||[]).join('\n'))}</textarea></div><div class="field span-2"><label>Previous projects</label><textarea name="previousProjects" placeholder="Project — domain — outcome">${esc((d.previousProjects||[]).join('\n'))}</textarea></div><label class="check-row span-2"><input name="available" type="checkbox" ${d.available!==false?'checked':''}/><span>Institution is currently available to receive new matched challenges.</span></label></div><div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="btn primary">Save capability profile</button></div></form>`}

function renderIndustry(){
 if(ui.page==='opportunities')return renderIndustryOpportunities(); if(ui.page==='offers')return renderIndustryOffers(); if(ui.page==='projects')return renderIndustryProjects(); if(ui.page==='transfer')return renderIndustryTransfer(); if(ui.page==='ip')return renderIPRegistry('industry'); if(ui.page==='capability')return renderIndustryCapability();
 const d=currentProfileData(),avail=availableForIndustry(),assigned=state.challenges.filter(c=>c.industryAssignment===session.id),offers=state.challenges.flatMap(c=>(c.industryOffers||[]).filter(o=>o.providerId===session.id));
 return `${pageHead('Industry / Partner','Support what can actually reach the field.','Industry participation is tied to concrete needs: mentorship, funding, prototype resources, pilot sites and technology transfer.',`<button class="btn primary" data-page-jump="opportunities">${icon('target','sm')} Explore opportunities</button>`)}${roleHero('Move research toward deployable capacity.','Inspect validated societal challenges, understand the context, then contribute exactly where your organisation has real capability.',[{label:'Open opportunities',value:avail.length,sub:'validated needs'},{label:'Assigned',value:assigned.length,sub:'to this partner'},{label:'Offers made',value:offers.length,sub:'recorded contributions'},{label:'Capability profile',value:profileCompleteness(d,'industry')+'%',sub:'complete'}])}<div class="grid asym"><section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('target')}</div><div><h3>Relevant opportunities</h3><p>Only validated challenge records are shown.</p></div></div></div>${avail.length?`<div class="list">${avail.slice(0,5).map(c=>challengeRow(c,'Inspect')).join('')}</div>`:emptyState('building','No open opportunity yet','Validated challenges will appear here. Your capability profile makes later matching explainable.')}</section><section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('network')}</div><div><h3>Partner readiness</h3><p>Declared capacity used for routing.</p></div></div></div>${capabilitySummary(d,'industry')}</section></div>`
}
function renderIndustryOpportunities(){const items=availableForIndustry();return `${pageHead('Discover','Open opportunities','Review real challenge evidence before committing mentorship, funding or implementation capacity.')}${items.length?`<div class="list">${items.map(c=>{const m=industryMatches(c).find(x=>x.profile.id===session.id);return `<div class="list-row"><div><h4>${esc(c.title)}</h4><p>${esc(c.aiSummary)}</p><div class="meta"><span class="badge ${c.status}">${c.status}</span><span class="tag">${esc(c.domain)}</span><span class="tag ${m?.score>=70?'good':m?.score>=45?'warn':''}">Capability match ${m?.score||15}%</span>${(m?.reasons||[]).slice(0,2).map(r=>`<span class="tag">${esc(r)}</span>`).join('')}</div></div><div style="display:flex;gap:6px"><button class="btn sm" data-open-challenge="${c.id}">Inspect</button>${!c.industryAssignment?`<button class="btn primary sm" data-industry-join="${c.id}">Express capacity</button>`:`<span class="tag good">Partner routed</span>`}</div></div>`}).join('')}</div>`:emptyState('target','No validated opportunity yet','The government review workflow creates the opportunity pool from validated societal challenges.')}`}
function renderIndustryOffers(){const items=state.challenges.filter(c=>['validated','assigned','in-progress','pilot'].includes(c.status));return `${pageHead('Support','Mentor / fund / resource','Make a concrete contribution against a real challenge. Every offer remains visible to the delivery team.')}${items.length?`<div class="grid two">${items.map(c=>`<section class="card"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.domain)} • ${esc(c.district)}</p></div><button class="btn sm" data-open-challenge="${c.id}">Context</button></div><form data-offer-form="${c.id}"><div class="form-grid"><div class="field"><label>Offer type</label><select name="type">${['Mentorship','Funding','Prototype Resource','Pilot Site','Technology Transfer'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Amount (₹, if funding)</label><input type="number" min="0" name="amount"/></div><div class="field span-2"><label>Details</label><textarea name="details" required placeholder="What exactly can your organisation contribute?"></textarea></div></div><div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="btn primary">Add contribution</button></div></form>${(c.industryOffers||[]).length?`<div class="section"><div class="section-title"><h3>Recorded offers</h3></div><div class="list">${c.industryOffers.map(o=>`<div class="list-row"><div><h4>${esc(o.type)} • ${esc(o.organization)}</h4><p>${esc(o.details)}</p></div><span class="tag ${o.providerId===session.id?'good':''}">${o.amount?`₹${Number(o.amount).toLocaleString('en-IN')}`:'Contribution'}</span></div>`).join('')}</div></div>`:''}</section>`).join('')}</div>`:emptyState('building','No challenge available for support','Once government validates a challenge, industry can contribute mentorship, funding, prototype resources or pilot sites.')}`}
function renderIndustryProjects(){const items=state.challenges.filter(c=>c.industryAssignment===session.id||c.industryOffers?.some(o=>o.providerId===session.id));return `${pageHead('Support','Co-development','Follow the same milestones, testing and pilot evidence as university and government partners.')}${items.length?items.map(c=>renderProjectWorkspace(c,'industry')).join(''):emptyState('layers','No co-development project yet','Join an opportunity or add a contribution to begin participating in delivery.')}`}
function renderIndustryTransfer(){const items=state.challenges.filter(c=>c.industryOffers?.some(o=>o.providerId===session.id&&o.type==='Technology Transfer')||c.industryAssignment===session.id);return `${pageHead('Scale','Technology transfer','Record transfer readiness, operating requirements, ownership and handover conditions for solutions moving beyond pilot.')}${items.length?items.map(c=>`<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.status)} • ${esc(c.domain)}</p></div></div><form data-transfer-form="${c.id}"><div class="form-grid"><div class="field span-2"><label>Technology / process being transferred</label><input name="technology" value="${esc(c.transfer?.technology||'')}"/></div><div class="field"><label>Receiving organisation</label><input name="receiver" value="${esc(c.transfer?.receiver||'')}"/></div><div class="field"><label>Transfer status</label><select name="status">${['Planning','Readiness review','Handover in progress','Transferred'].map(x=>`<option ${c.transfer?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span-2"><label>Operating / maintenance conditions</label><textarea name="conditions">${esc(c.transfer?.conditions||'')}</textarea></div></div><div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="btn primary">Save transfer record</button></div></form></section>`).join(''):emptyState('network','No transfer candidate yet','Technology-transfer tracking becomes useful once your organisation is supporting a challenge or pilot.')}`}
function renderIndustryCapability(){const d=currentProfileData();return `${pageHead('Organisation','Capability profile','Jharkhandi matches industry only against capacity your organisation explicitly records.')}
 <form class="card" id="industry-capability-form"><div class="form-grid"><div class="field"><label>Technology capabilities</label><textarea name="capabilities" placeholder="One capability per line">${esc((d.capabilities||[]).join('\n'))}</textarea></div><div class="field"><label>Technologies / platforms</label><textarea name="technologies" placeholder="One technology per line">${esc((d.technologies||[]).join('\n'))}</textarea></div><div class="field"><label>Mentor expertise</label><textarea name="mentorSkills" placeholder="One mentor skill per line">${esc((d.mentorSkills||[]).join('\n'))}</textarea></div><div class="field"><label>Prototype resources</label><textarea name="prototypeResources" placeholder="Lab, machine, cloud, equipment…">${esc((d.prototypeResources||[]).join('\n'))}</textarea></div><div class="field"><label>Pilot sites</label><textarea name="pilotSites" placeholder="Site / location per line">${esc((d.pilotSites||[]).join('\n'))}</textarea></div><div class="field"><label>Funding capacity (₹)</label><input type="number" min="0" name="fundingCapacity" value="${num(d.fundingCapacity)||''}"/></div><div class="field span-2"><label>Technology transfer / deployment capacity</label><textarea name="transferCapacity">${esc(d.transferCapacity||'')}</textarea></div><label class="check-row span-2"><input name="mentorAvailable" type="checkbox" ${d.mentorAvailable!==false?'checked':''}/><span>Mentors are currently available for new matched projects.</span></label></div><div class="form-actions"><button class="btn primary">Save partner capability</button></div></form>`}

function renderGovernment(){
 if(ui.page==='review')return renderGovernmentReview(); if(ui.page==='intelligence')return renderGovernmentIntel(); if(ui.page==='assignments')return renderAssignments(); if(ui.page==='projects')return renderGovernmentProjects(); if(ui.page==='impact')return renderImpact(); if(ui.page==='ip')return renderIPRegistry('government'); if(ui.page==='analytics')return renderAnalytics(); if(ui.page==='memory')return renderMemory(); if(ui.page==='activity')return renderAudit();
 const q=state.challenges.filter(c=>['submitted','under-review'].includes(c.status)),valid=state.challenges.filter(c=>c.status==='validated'),active=state.challenges.filter(c=>['assigned','in-progress','pilot'].includes(c.status)),closed=state.challenges.filter(c=>c.status==='closed');
 return `${pageHead('Government / Admin','Decision Centre','A single queue for evidence review, decision intelligence, capability routing, delivery monitoring and impact verification.',`<button class="btn primary" data-page-jump="review">${icon('shield','sm')} Review queue</button>`)}
 ${roleHero('Make fewer blind decisions.','Jharkhandi asks whether a problem has been solved before, whether that solution transfers to this context, why a new project could fail and what impact is actually verified.',[{label:'Review queue',value:q.length,sub:'needs validation'},{label:'Validated',value:valid.length,sub:'ready to route'},{label:'In delivery',value:active.length,sub:'assigned / pilot'},{label:'Innovation memory',value:closed.length,sub:'closed learnings'}])}
 <div class="grid asym"><section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('shield')}</div><div><h3>Action queue</h3><p>Only records requiring a real government action appear here.</p></div></div></div>${q.length?`<div class="list">${q.slice(0,6).map(c=>challengeRow(c,'Review')).join('')}</div>`:emptyState('check','Review queue is clear','New citizen submissions will appear here immediately through live local sync.')}</section><section class="card"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon('brain')}</div><div><h3>Decision intelligence</h3><p>The layer that differentiates Jharkhandi from a generic portal.</p></div></div></div><div class="timeline">${[['Understand','Challenge DNA, family, root-cause hypotheses'],['Decide','Reuse / Adapt / Invent + transferability'],['De-risk','Failure learning + pre-mortem'],['Route','Explainable HEI + industry capability match'],['Verify','Claim vs evidence Impact Integrity'],['Remember','Successes and failures become future evidence']].map(x=>`<div class="timeline-item"><b>${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div></section></div>`
}
function renderGovernmentReview(){const items=state.challenges.filter(c=>['submitted','under-review'].includes(c.status));return `${pageHead('Intake','Review & validate','Inspect citizen evidence, AI classification, priority and duplicate signals before validating a challenge.')}${items.length?items.map(c=>`<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.aiSummary)}</p><div class="meta" style="margin-top:7px"><span class="tag">${esc(c.domain)}</span><span class="tag">${esc(c.district)}</span><span class="tag ${c.priorityScore>=75?'bad':'warn'}">Priority ${c.priorityScore}</span>${c.duplicateOf?`<span class="tag warn">Possible duplicate ${Math.round(num(c.duplicateScore)*100)}%</span>`:''}</div></div><button class="btn sm" data-open-challenge="${c.id}">Full context</button></div><div class="grid two"><div class="dna-item"><small>Evidence files</small><b>${(c.evidence||[]).length}</b></div><div class="dna-item"><small>Community confirmations</small><b>${num(c.communityValidations)}</b></div></div><div style="display:flex;justify-content:flex-end;gap:7px;margin-top:12px"><button class="btn danger" data-reject="${c.id}">Reject / moderate</button><button class="btn primary" data-validate="${c.id}">${icon('check','sm')} Validate challenge</button></div></section>`).join(''):emptyState('check','No submission is waiting','The queue updates when citizens submit new problems.')}`}
function renderGovernmentIntel(){const c=selectedOrFirst(x=>['validated','assigned','in-progress','pilot','closed'].includes(x.status));if(!c)return `${pageHead('Decide','Decision intelligence','The intelligence layer becomes available after a challenge is validated.')}${emptyState('brain','No validated challenge yet','Validate a citizen submission first.')}`;const t=transferDecision(c),family=relatedFamily(c);return `${pageHead('Decide','Decision intelligence','Inspect structured context, transferability, failure learning and project pre-mortem.',`<button class="btn" data-open-challenge="${c.id}">Open challenge cockpit</button>`)}
 <div class="cockpit"><div class="grid"><section class="card"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.aiSummary)}</p></div><span class="badge ${c.status}">${c.status}</span></div>${journeyHtml(c)}<div class="dna-grid">${[['Domain',c.domain],['Sub-domain',c.subDomain],['Challenge language',c.submissionLanguage||'English'],['District',c.district],['Affected population',c.affectedPopulation||0],['Priority score',c.priorityScore],['Classification confidence',Math.round(num(c.classificationConfidence)*100)+'%']].map(x=>`<div class="dna-item"><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div></section>
 <section class="card"><div class="card-head"><div><h3>Problem family & root causes</h3><p>Related reports are grouped instead of treated as isolated tickets.</p></div></div><div class="grid two"><div class="family-tree"><div class="family-root">${esc(c.id)} • ${esc(c.domain)}</div><div class="family-line"></div><div class="family-children">${family.length?family.map(x=>`<button class="family-child" data-open-challenge="${x.id}">${esc(x.id)} • ${esc(x.district)}</button>`).join(''):'<span class="muted" style="font-size:9px">No related challenge yet</span>'}</div></div><div class="root-list">${(c.reviewedRootCauses||c.rootCauses||[]).map(x=>`<div class="root-item"><i></i><span>${esc(x)}</span></div>`).join('')}</div></div></section>
 <section class="card"><div class="card-head"><div><h3>What-if decision support</h3><p>Compare budget, speed and resilience assumptions without pretending to predict certainty.</p></div></div><div class="whatif-controls"><div class="range-card"><label>Budget multiplier <b id="wi-budget">1.0×</b></label><input id="wi-budget-range" type="range" min="50" max="180" value="100"/></div><div class="range-card"><label>Timeline multiplier <b id="wi-time">1.0×</b></label><input id="wi-time-range" type="range" min="60" max="160" value="100"/></div><div class="range-card"><label>Reach target <b id="wi-reach">100%</b></label><input id="wi-reach-range" type="range" min="50" max="150" value="100"/></div></div><div class="compare-grid" id="whatif-results"></div></section></div>
 <aside class="grid"><section class="decision-banner"><small>REUSE / ADAPT / INVENT</small><h3>${t.decision}</h3><p>${esc(t.reason)}</p><div style="margin-top:13px"><span class="tag good">Transferability ${t.score}%</span></div></section><section class="card"><div class="card-head"><div><h3>Transfer safeguards</h3><p>Required changes before a prior solution is reused.</p></div></div><div class="root-list">${t.adaptations.map(x=>`<div class="root-item"><i></i><span>${esc(x)}</span></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h3>Failure learning</h3><p>Warnings retrieved from failed / partial Innovation Memory records.</p></div></div>${failureLearning(c)}</section></aside></div>`}
function failureLearning(c){const past=state.challenges.filter(x=>x.status==='closed'&&['failed','partial'].includes(x.outcome)&&x.id!==c.id&&(x.domain===c.domain||similarity(x.title,c.title)>.2));return past.length?past.map(x=>`<div class="premortem-row"><header><b>${esc(x.title)}</b><span class="tag bad">${esc(x.outcome)}</span></header><p>${esc(x.lessons||'No lesson recorded.')}</p></div>`).join(''):'<div class="empty" style="padding:18px"><p>No relevant failure record exists in Innovation Memory yet.</p></div>'}
function renderAssignments(){
 const items=state.challenges.filter(c=>['validated','assigned','in-progress'].includes(c.status))
 return `${pageHead('Route','Route partners','Compare registered capability profiles first, then use the official Jharkhand HEI directory as a verified institution-name reference. Inferred capability hints must be confirmed by the institution.')}${items.length?items.map(c=>{const us=universityMatches(c),official=officialUniversityMatches(c),ins=industryMatches(c);return `<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>Required skills: ${requiredSkills(c).map(esc).join(' • ')}</p></div><button class="btn sm" data-open-challenge="${c.id}">Context</button></div><div class="grid two"><div><div class="section-title"><div><h3>University candidates</h3><p>Registered capability profiles have highest trust.</p></div></div>${us.length?`<div class="list">${us.slice(0,4).map(m=>`<div class="list-row"><div><h4>${esc(m.profile.organization||m.profile.name)}</h4><p>${m.reasons.map(esc).join(' • ')}</p><div class="meta"><span class="tag good">Registered profile</span></div></div><button class="btn sm ${c.universityAssignment===m.profile.id?'primary':''}" data-assign-uni="${c.id}" data-profile="${m.profile.id}">${c.universityAssignment===m.profile.id?'Assigned':m.score+'% • Assign'}</button></div>`).join('')}</div>`:''}<div class="directory-block"><div class="directory-head"><span>${icon('university','sm')}</span><div><b>Jharkhand official HEI directory</b><small>${referenceData.institutions.length} institution names loaded · capability hints are inferred, not official claims</small></div></div><div class="list">${official.slice(0,4).map(m=>`<div class="list-row directory-row"><div><h4>${esc(m.inst.name)}</h4><p>${m.reasons.map(esc).join(' • ')}</p><div class="meta"><span class="tag">${esc(m.inst.type||'HEI')}</span><span class="tag">${esc(m.inst.district||'Jharkhand')}</span></div></div><button class="btn sm" data-assign-official-uni="${c.id}" data-official-index="${m.index}">${m.score}% • Link & assign</button></div>`).join('')}</div></div></div><div><div class="section-title"><div><h3>Industry candidates</h3><p>Only organisations that have registered capabilities appear here.</p></div></div>${ins.length?`<div class="list">${ins.slice(0,4).map(m=>`<div class="list-row"><div><h4>${esc(m.profile.organization||m.profile.name)}</h4><p>${m.reasons.map(esc).join(' • ')}</p></div><button class="btn sm ${c.industryAssignment===m.profile.id?'primary':''}" data-assign-ind="${c.id}" data-profile="${m.profile.id}">${c.industryAssignment===m.profile.id?'Assigned':m.score+'% • Assign'}</button></div>`).join('')}</div>`:emptyState('building','No registered industry capability yet','Industry matching intentionally avoids fabricated company data. Register a partner profile to make routing evidence-based.')}</div></div></section>`}).join(''):emptyState('route','Nothing is ready to route','Validate a challenge first.')}`
}
function renderGovernmentProjects(){const items=state.challenges.filter(c=>c.proposal||['assigned','in-progress','pilot'].includes(c.status));return `${pageHead('Delivery','Delivery monitor','Track proposals, milestones, risks, testing, pilot and deployment evidence across active projects.')}${items.length?items.map(c=>renderProjectWorkspace(c,'government')).join(''):emptyState('layers','No project is in delivery','A project appears after routing and proposal submission.')}`}
function renderImpact(){const items=state.challenges.filter(c=>['pilot','closed'].includes(c.status)||c.testingOutcome||c.deploymentNote);return `${pageHead('Verify','Impact verification','Separate claimed results from evidence using baseline, post-deployment measurement, community validation and government verification.')}${items.length?items.map(c=>renderImpactForm(c)).join(''):emptyState('target','No project is ready for impact verification','Move a project through prototype, testing and pilot first.')}`}
function renderIPRegistry(mode='government'){const items=state.challenges.filter(c=>c.proposal||c.status==='pilot'||c.status==='closed'||(c.ipRecords||[]).length);const records=items.flatMap(c=>(c.ipRecords||[]).map(r=>({...r,challengeId:c.id,challengeTitle:c.title,domain:c.domain,district:c.district})));const editable=mode==='university'||mode==='government';return `${pageHead('Innovation assets',mode==='government'?'IP & patent registry':'IP & innovation','Track intellectual-property generation from prototype to filing, ownership, grant/licensing and technology transfer.')} ${metrics([{label:'IP records',value:records.length,sub:'linked to projects',icon:'book'},{label:'Patents',value:records.filter(r=>r.type==='Patent').length,sub:'applications / grants',icon:'shield'},{label:'Filed / granted',value:records.filter(r=>['Filed','Published','Granted','Licensed'].includes(r.status)).length,sub:'progressed records',icon:'check'},{label:'Projects with IP',value:items.filter(c=>(c.ipRecords||[]).length).length,sub:'innovation outcomes',icon:'layers'}])}${items.length?items.map(c=>`<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.id)} • ${esc(c.domain)} • ${esc(c.district)}</p></div><span class="tag">${(c.ipRecords||[]).length} IP record${(c.ipRecords||[]).length===1?'':'s'}</span></div>${(c.ipRecords||[]).length?`<div class="list">${c.ipRecords.map(r=>`<div class="list-row"><div><h4>${esc(r.type)} • ${esc(r.title)}</h4><p>${esc(r.applicationNumber||'Application number pending')} • Owner: ${esc(r.owner||'Not recorded')} • ${esc(r.filingDate||'Filing date pending')}</p><div class="meta"><span class="tag ${['Granted','Licensed'].includes(r.status)?'good':r.status==='Filed'?'warn':''}">${esc(r.status||'Draft')}</span>${r.notes?`<span class="tag">${esc(r.notes)}</span>`:''}</div></div>${editable?`<button type="button" class="btn sm" data-ip-delete="${c.id}" data-ip-id="${r.id}">${icon('trash','sm')} Remove</button>`:''}</div>`).join('')}</div>`:''}${editable?`<form data-ip-form="${c.id}" class="section"><div class="form-grid"><div class="field"><label>IP type</label><select name="type">${['Patent','Copyright','Industrial Design','Trademark','Know-how / Trade Secret'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Draft','Disclosure recorded','Prior-art review','Filed','Published','Granted','Licensed'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field span-2"><label>IP / invention title</label><input name="title" required placeholder="Name of invention, design, software or process"/></div><div class="field"><label>Application / reference number</label><input name="applicationNumber" placeholder="Optional until filing"/></div><div class="field"><label>Owner / assignee</label><input name="owner" placeholder="University / inventors / joint ownership"/></div><div class="field"><label>Filing date</label><input type="date" name="filingDate"/></div><div class="field"><label>Notes / licensing condition</label><input name="notes" placeholder="Prior art, ownership, licence, transfer condition…"/></div></div><div class="form-actions"><button class="btn primary">Add IP record</button></div></form>`:''}</section>`).join(''):emptyState('book','No innovation asset yet','IP tracking becomes available once a project has a proposal, prototype, pilot or recorded innovation outcome.')}`}

function renderAnalytics(){const ch=state.challenges,total=ch.length,domains=DOMAINS.map(d=>[d,ch.filter(c=>c.domain===d).length]).filter(x=>x[1]);const districts=[...new Set(ch.map(c=>c.district).filter(Boolean))].map(d=>[d,ch.filter(c=>c.district===d).length]).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...domains.map(x=>x[1]));const statuses=['submitted','under-review','validated','assigned','in-progress','pilot','closed'];const closed=ch.filter(c=>c.status==='closed').length,completionRate=total?Math.round(closed/total*100):0;const universityParticipation=new Set(ch.map(c=>c.universityAssignment).filter(Boolean)).size,industryParticipation=new Set(ch.map(c=>c.industryAssignment).filter(Boolean)).size;const impacts=ch.map(c=>c.impact||{}),beneficiaries=impacts.reduce((a,i)=>a+num(i.beneficiaryCount),0),jobs=impacts.reduce((a,i)=>a+num(i.jobsCreated),0),startups=impacts.reduce((a,i)=>a+num(i.startupsCreated),0),patentOutputs=impacts.reduce((a,i)=>a+num(i.patentsGenerated),0),ipRecords=ch.reduce((a,c)=>a+(c.ipRecords||[]).length,0);return `${pageHead('Learn','System analytics','Real-time challenge, participation, collaboration, project, innovation and social-impact analytics computed from this deployment.',`<button class="btn" id="export-data">${icon('download','sm')} Export data</button>`)}${metrics([{label:'Challenges',value:total,sub:'all records',icon:'target'},{label:'Completion rate',value:completionRate+'%',sub:`${closed} closed`,icon:'check'},{label:'University participation',value:universityParticipation,sub:'institutions assigned',icon:'university'},{label:'Industry engagement',value:industryParticipation,sub:'partners assigned',icon:'building'}])}<div class="grid four section">${[['Verified beneficiaries',beneficiaries.toLocaleString('en-IN'),'community impact'],['Jobs created',jobs,'innovation outcome'],['Startups created',startups,'entrepreneurship outcome'],['IP / patent outputs',Math.max(patentOutputs,ipRecords),'impact + registry records']].map(x=>`<div class="metric-card"><div class="label">${icon('chart','sm')} ${x[0]}</div><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}</div><div class="grid two section"><section class="card"><div class="card-head"><div><h3>Domain distribution</h3><p>Challenge volume by thematic sector.</p></div></div>${domains.length?`<div class="chart">${domains.map(([d,n])=>`<div class="bar-col"><div class="bar" style="height:${Math.max(4,n/max*150)}px"></div><b>${n}</b><small>${esc(d)}</small></div>`).join('')}</div>`:emptyState('chart','No analytics yet','Submit challenges to populate domain analytics.')}</section><section class="card"><div class="card-head"><div><h3>Lifecycle & completion</h3><p>Project progress from submission through verified closure.</p></div></div><div class="list">${statuses.map(s=>{const n=ch.filter(c=>c.status===s).length;return `<div class="list-row"><div><h4>${s.replace('-',' ')}</h4><p>${n} challenge${n===1?'':'s'}</p></div><div style="width:150px"><div class="priority-meter"><i style="width:${total?Math.round(n/total*100):0}%"></i></div></div></div>`}).join('')}</div></section></div><div class="grid two section"><section class="card"><div class="card-head"><div><h3>District-wise challenge load</h3><p>Geographic distribution across reported districts.</p></div></div>${districts.length?`<div class="list">${districts.slice(0,12).map(([d,n])=>`<div class="list-row"><div><h4>${esc(d)}</h4><p>${n} challenge${n===1?'':'s'} • ${ch.filter(c=>c.district===d&&c.impact?.governmentVerified).length} verified impact${ch.filter(c=>c.district===d&&c.impact?.governmentVerified).length===1?'':'s'}</p></div><span class="tag">${total?Math.round(n/total*100):0}%</span></div>`).join('')}</div>`:emptyState('map','No district analytics yet','District data appears as citizens submit challenges.')}</section><section class="card"><div class="card-head"><div><h3>District × sector outcomes</h3><p>Compact view of challenge volume and verified beneficiaries.</p></div></div>${districts.length?`<div class="list">${districts.slice(0,10).map(([d,n])=>{const ds=ch.filter(c=>c.district===d),top=[...new Set(ds.map(c=>c.domain))].map(dom=>[dom,ds.filter(c=>c.domain===dom).length]).sort((a,b)=>b[1]-a[1])[0];const ben=ds.reduce((a,c)=>a+num(c.impact?.beneficiaryCount),0);return `<div class="list-row"><div><h4>${esc(d)} • ${esc(top?.[0]||'No sector')}</h4><p>${n} challenges • ${ben.toLocaleString('en-IN')} beneficiaries • ${ds.filter(c=>c.status==='closed').length} closed</p></div><span class="tag ${ben?'good':''}">${ben?'impact recorded':'awaiting impact'}</span></div>`}).join('')}</div>`:''}</section></div>`}
function renderMemory(){const items=state.challenges.filter(c=>c.status==='closed');return `${pageHead('Learn','Innovation Memory','Every completed project becomes reusable knowledge connecting challenge, context, solution, outcome, failure reason and lesson.')}${items.length?`<div class="grid two">${items.map(c=>{const t=transferDecision(c);return `<section class="card"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.domain)} • ${esc(c.district)} • closed ${fmtDate(c.updatedAt)}</p></div><span class="tag ${c.outcome==='successful'?'good':c.outcome==='failed'?'bad':'warn'}">${esc(c.outcome||'outcome pending')}</span></div><div class="dna-grid">${[['Problem',c.aiSummary],['Context',`${c.district}; ${c.affectedPopulation||0} affected`],['Solution',c.proposal?.summary||'—'],['Outcome',c.outcome||'—'],['Lesson',c.lessons||'—'],['Impact integrity',(c.impact?.integrityScore||0)+'%']].map(x=>`<div class="dna-item"><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div><button class="btn" style="margin-top:12px" data-open-challenge="${c.id}">Open knowledge record</button></section>`}).join('')}</div>`:emptyState('book','Innovation Memory is empty','A project enters memory only after closure. Successful, partial and failed outcomes are all valuable evidence.')}`}
function renderAudit(){return `${pageHead('Governance','Audit trail','Every material platform action is timestamped with the actor and entity for reviewability.')}${state.activity.length?`<div class="card"><div class="timeline">${state.activity.map(a=>`<div class="timeline-item"><b>${esc(a.action)}</b><small>${esc(a.actor)} • ${a.entityId?esc(a.entityId)+' • ':''}${fmtDate(a.createdAt)}</small></div>`).join('')}</div></div>`:emptyState('activity','No activity yet','Platform actions will appear here.')}`}

function renderProjectWorkspace(c,mode){const ms=c.milestones||[],risk=c.riskRegister||[],approved=num(c.approvedBudget||c.proposal?.estimatedCost),spent=num(c.budgetSpent),budgetPct=approved?Math.min(100,Math.round(spent/approved*100)):0;return `<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.id)} • ${esc(c.domain)} • ${esc(c.status)}</p></div><button class="btn sm" data-open-challenge="${c.id}">Challenge cockpit</button></div>${journeyHtml(c)}<div class="delivery-kpis"><div><small>Approved budget</small><b>₹${approved.toLocaleString('en-IN')}</b></div><div><small>Spend recorded</small><b>₹${spent.toLocaleString('en-IN')}</b><span>${budgetPct}% of approved</span></div><div><small>Prototype</small><b>${esc(c.prototypeStatus||'Not recorded')}</b></div><div><small>Milestone verification</small><b>${ms.filter(x=>x.verified).length}/${ms.length}</b></div></div><div class="grid two"><div><div class="section-title"><div><h3>Milestones, tasks & deliverables</h3><p>${ms.filter(x=>x.status==='completed').length}/${ms.length} complete</p></div></div>${ms.length?`<div class="list">${ms.map(m=>`<div class="list-row"><div><h4>${esc(m.kind||'Milestone')} • ${esc(m.title)}</h4><p>${esc(m.owner||'Owner pending')} • due ${esc(m.dueDate||'—')} ${m.evidenceNote?'• '+esc(m.evidenceNote):''}</p><div class="meta"><span class="tag ${m.status==='completed'?'good':'warn'}">${esc(m.status)}</span>${m.verified?'<span class="tag good">Government verified</span>':''}</div></div>${mode==='university'?`<button class="btn sm" data-milestone-toggle="${c.id}" data-mid="${m.id}">${m.status==='completed'?'Reopen':'Complete'}</button>`:mode==='government'&&m.status==='completed'?`<button class="btn sm ${m.verified?'primary':''}" data-milestone-verify="${c.id}" data-mid="${m.id}">${m.verified?'Verified':'Verify'}</button>`:`<span class="tag ${m.status==='completed'?'good':'warn'}">${m.status}</span>`}</div>`).join('')}</div>`:emptyState('layers','No milestone yet','Create tasks and deliverables to make project progress auditable.')}${mode==='university'?`<form data-milestone-form="${c.id}" class="section"><div class="form-grid"><div class="field"><label>Title</label><input name="title" required/></div><div class="field"><label>Kind</label><select name="kind"><option>Milestone</option><option>Task</option><option>Deliverable</option><option>Approval</option></select></div><div class="field"><label>Owner</label><input name="owner"/></div><div class="field"><label>Due date</label><input name="dueDate" type="date"/></div></div><button class="btn" style="margin-top:8px">Add item</button></form>`:''}</div><div><div class="section-title"><h3>Budget, prototype, risk & testing</h3></div><div class="root-list">${risk.length?risk.map(r=>`<div class="root-item"><i></i><span>${esc(r)}</span></div>`).join(''):'<div class="root-item"><i></i><span>No explicit risk added yet. Pre-mortem remains available in the proposal.</span></div>'}</div>${mode==='university'?`<form data-delivery-form="${c.id}" class="section"><div class="form-grid"><div class="field"><label>Approved / working budget (₹)</label><input type="number" min="0" name="approvedBudget" value="${approved||''}"/></div><div class="field"><label>Spend recorded (₹)</label><input type="number" min="0" name="budgetSpent" value="${spent||''}"/></div><div class="field"><label>Prototype status</label><select name="prototypeStatus">${['Not started','In build','Prototype ready','Prototype validated'].map(x=>`<option ${c.prototypeStatus===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Prototype evidence / note</label><input name="prototypeNote" value="${esc(c.prototypeNote||'')}" placeholder="Prototype version, evidence or test artefact"/></div><div class="field span-2"><label>Risk register (one per line)</label><textarea name="riskRegister">${esc(risk.join('\n'))}</textarea></div><div class="field span-2"><label>Testing outcome</label><textarea name="testingOutcome">${esc(c.testingOutcome||'')}</textarea></div><div class="field span-2"><label>Pilot note</label><textarea name="pilotNote">${esc(c.pilotNote||'')}</textarea></div><div class="field span-2"><label>Deployment / handover note</label><textarea name="deploymentNote">${esc(c.deploymentNote||'')}</textarea></div></div><div class="form-actions"><button class="btn">Save delivery evidence</button><button type="button" class="btn primary" data-enter-pilot="${c.id}">Enter pilot</button></div></form>`:`<div class="section delivery-readout"><div class="dna-item"><small>Prototype</small><b>${esc(c.prototypeStatus||'Not recorded')}</b><span>${esc(c.prototypeNote||'')}</span></div><div class="dna-item"><small>Testing outcome</small><b>${esc(c.testingOutcome||'Not recorded')}</b></div><div class="dna-item"><small>Pilot note</small><b>${esc(c.pilotNote||'Not recorded')}</b></div><div class="dna-item"><small>Deployment / handover</small><b>${esc(c.deploymentNote||'Not recorded')}</b></div></div>`}</div></div>${mode==='industry'?`<div class="section industry-feedback-panel"><div class="section-title"><div><h3>Implementation feedback</h3><p>Record field, manufacturability, maintenance or deployment feedback for the university and government.</p></div></div>${(c.industryFeedback||[]).length?`<div class="list">${c.industryFeedback.map(x=>`<div class="list-row"><div><h4>${esc(x.organization||x.author)}</h4><p>${esc(x.text)}</p><div class="meta"><span class="tag">${fmtDate(x.createdAt)}</span></div></div></div>`).join('')}</div>`:''}<form data-industry-feedback-form="${c.id}" class="section"><div class="field"><label>Implementation feedback</label><textarea name="feedback" required placeholder="Manufacturability, maintenance, procurement, field deployment or scale feedback…"></textarea></div><div class="form-actions"><button class="btn primary">Save implementation feedback</button></div></form></div>`:(c.industryFeedback||[]).length?`<div class="section"><div class="section-title"><div><h3>Industry implementation feedback</h3><p>Feedback from delivery partners.</p></div></div><div class="list">${c.industryFeedback.map(x=>`<div class="list-row"><div><h4>${esc(x.organization||x.author)}</h4><p>${esc(x.text)}</p></div><span class="tag">${fmtDate(x.createdAt)}</span></div>`).join('')}</div></div>`:''}</section>`}

function renderImpactForm(c){const i=c.impact||{};return `<section class="card section"><div class="card-head"><div><h3>${esc(c.title)}</h3><p>${esc(c.id)} • ${esc(c.status)}</p></div><div class="score-wrap"><div class="score-ring" style="--p:${impactScore(i)}"><div><b>${impactScore(i)}%</b><small>Integrity</small></div></div></div></div><form data-impact-form="${c.id}"><div class="form-grid"><div class="field"><label>Impact metric</label><input name="metricName" value="${esc(i.metricName||'')}" placeholder="e.g. average daily water availability"/></div><div class="field"><label>Beneficiary count</label><input type="number" min="0" name="beneficiaryCount" value="${num(i.beneficiaryCount)||''}"/></div><div class="field"><label>Baseline value</label><input type="number" step="any" name="baselineValue" value="${i.baselineValue??''}"/></div><div class="field"><label>Post-deployment value</label><input type="number" step="any" name="postValue" value="${i.postValue??''}"/></div><div class="field"><label>Community validation (0–5)</label><input type="number" min="0" max="5" step=".1" name="communityScore" value="${i.communityScore??''}"/></div><div class="field"><label>Jobs / startups / patents</label><input name="outputs" value="${esc([i.jobsCreated||0,i.startupsCreated||0,i.patentsGenerated||0].join(' / '))}" placeholder="jobs / startups / patents"/></div><div class="field span-2"><label>Evidence note</label><textarea name="evidenceNote">${esc(i.evidenceNote||'')}</textarea></div><div class="field span-2"><label>Impact evidence files</label><input type="file" multiple name="impactEvidence" accept="image/*,.pdf,.txt"/></div></div><div style="display:flex;gap:7px;justify-content:flex-end;margin-top:10px"><button class="btn">Save impact evidence</button>${session.role==='government'?`<button type="button" class="btn primary" data-verify-impact="${c.id}">${icon('shield','sm')} Verify & close project</button>`:''}</div></form></section>`}

function renderNotifications(){const items=state.notifications.filter(n=>!n.role||n.role===session.role);return `${pageHead('Account','Notifications','Real-time workflow alerts are created by workflow actions performed by other roles.',`<button class="btn" id="mark-read">Mark all read</button>`)}${items.length?`<div class="card"><div class="list">${items.map(n=>`<div class="list-row"><div><h4>${esc(n.title)}</h4><p>${esc(n.message)}</p><div class="meta"><span class="tag ${n.read?'':'good'}">${n.read?'Read':'New'}</span><span class="tag">${fmtDate(n.createdAt)}</span></div></div></div>`).join('')}</div></div>`:emptyState('bell','No notification yet','Workflow events will appear here as other stakeholders act on challenges.')}`}
function renderProfile(){const r=ROLE_META[session.role];return `${pageHead('Account','Profile & settings','Identity, language, accessibility, low-bandwidth mode and workspace data controls.')}
 <div class="grid asym"><form class="card" id="profile-form"><div class="card-head"><div class="card-title-row"><div class="card-icon">${icon(r.icon)}</div><div><h3>${r.label} profile</h3><p>This identity is used in the audit trail and matching context.</p></div></div></div><div class="form-grid"><div class="field"><label>Name</label><input name="name" value="${esc(session.name)}" required/></div><div class="field"><label>Email / ID</label><input name="email" value="${esc(session.email)}" required/></div><div class="field"><label>Stakeholder / organisation type</label><select name="stakeholderType">${stakeholderOptions(session.role,session.stakeholderType||'')}</select></div><div class="field"><label>Organisation</label><input name="organization" value="${esc(session.organization||'')}"/></div><div class="field"><label>District</label><input name="district" value="${esc(session.district||'')}"/></div></div><div style="display:flex;justify-content:flex-end;margin-top:10px"><button class="btn primary">Save profile</button></div></form>
 <section class="card"><div class="card-head"><div><h3>Application settings</h3><p>PWA and accessibility controls.</p></div></div><div class="list"><label class="check-row"><input id="high-contrast" type="checkbox" ${state.settings.highContrast?'checked':''}/><span>High contrast interface</span></label><label class="check-row"><input id="low-bandwidth" type="checkbox" ${state.settings.lowBandwidth?'checked':''}/><span>Low-bandwidth mode</span></label><div class="field"><label>Language</label><select id="language">${languageOptionsHtml()}</select><div class="helper">Interface language changes the public site, navigation and core workspace controls. Full editorial packs are bundled for English, हिन्दी, বাংলা, भोजपुरी, मगही, मैथिली, اردو and ଓଡ଼ିଆ; community-draft packs are provided for the remaining Jharkhand languages and should receive native-speaker review before official rollout.</div></div><button class="btn" id="export-data">${icon('download','sm')} Export workspace data</button><label class="btn" style="cursor:pointer">${icon('upload','sm')} Import workspace data<input id="import-data" type="file" accept="application/json" hidden/></label></div></section></div>`}

function renderChallengeModal(c){
 const t=transferDecision(c),family=relatedFamily(c),comments=c.comments||[],ctx=c.liveContext||{},alts=c.classificationAlternatives||[]
 const classifierMeta=c.classificationSource?`<div class="classifier-strip"><span>${icon('brain','sm')}</span><div><small>CLASSIFICATION SOURCE</small><b>${esc(c.classificationSource)}</b></div><div><small>TRAINING / CORRECTIONS</small><b>${num(c.classificationTrainingExamples)||referenceData.model?.trainingExamples||'—'} / ${num(c.classificationFeedbackExamples)||referenceData.model?.reviewerCorrections||0}</b></div></div>`:''
 const govCorrection=session.role==='government'?`<form id="classification-correction-form" data-cid="${c.id}" class="classification-correction"><div><small>HUMAN-IN-THE-LOOP</small><b>Correct the domain if the trained suggestion is wrong.</b></div><select name="domain">${DOMAINS.map(d=>`<option ${c.domain===d?'selected':''}>${d}</option>`).join('')}</select><button class="btn" type="submit">Save correction</button></form>`:''
 const rootReview=session.role==='government'?`<form id="root-cause-review-form" data-cid="${c.id}" class="review-panel"><div><small>HUMAN REVIEW · ROOT CAUSE</small><b>Approve, edit or replace the AI hypotheses before routing.</b></div><textarea name="rootCauses">${esc((c.reviewedRootCauses||c.rootCauses||[]).join('\n'))}</textarea><button class="btn" type="submit">Save reviewed causes</button></form>`:''
 const decisionReview=session.role==='government'?`<form id="decision-review-form" data-cid="${c.id}" class="review-panel decision-review"><div><small>HUMAN REVIEW · DECISION</small><b>Approve or override the Reuse / Adapt / Invent recommendation.</b></div><select name="decision">${['REUSE','ADAPT','INVENT','HOLD FOR EVIDENCE'].map(x=>`<option ${String(c.decisionReview?.decision||t.decision)===x?'selected':''}>${x}</option>`).join('')}</select><input name="note" value="${esc(c.decisionReview?.note||'')}" placeholder="Reviewer rationale / evidence note"/><button class="btn" type="submit">Save reviewed decision</button></form>`:''
 return `<div class="modal-backdrop" id="modal-backdrop"><div class="modal"><div class="modal-head"><div><span class="smallcaps">${esc(c.id)} • Challenge cockpit</span><h3>${esc(c.title)}</h3></div><button class="modal-close" id="modal-close">${icon('x','sm')}</button></div><div class="modal-body">${journeyHtml(c)}${classifierMeta}
 <div class="grid two"><section class="card"><div class="card-head"><div><h3>Challenge DNA</h3><p>Structured context used throughout the decision process.</p></div></div><div class="dna-grid">${[['Domain',c.domain],['Sub-domain',c.subDomain],['Challenge language',c.submissionLanguage||'English'],['District',c.district],['Block / village',[c.block,c.village].filter(Boolean).join(' / ')||'—'],['Affected',c.affectedPopulation||0],['Severity / urgency',`${c.severity}/5 • ${c.urgency}/5`],['Priority',c.priorityScore],['Classifier confidence',Math.round(num(c.classificationConfidence)*100)+'%'],['Required skills',(c.requiredSkills||[]).join(', ')||'—']].map(x=>`<div class="dna-item"><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div>${alts.length?`<div class="prediction-stack"><small>TOP CLASSIFIER ALTERNATIVES</small>${alts.map((x,i)=>`<span class="${i===0?'top':''}"><b>${esc(x.domain)}</b><em>${Math.round(num(x.confidence)*100)}%</em></span>`).join('')}</div>`:''}${govCorrection}<div class="section"><div class="section-title"><h3>AI summary</h3></div><p class="muted modal-copy">${esc(c.aiSummary)}</p></div></section>
 <section class="card"><div class="card-head"><div><h3>Decision layer</h3><p>Transferability and safeguards from current Innovation Memory.</p></div></div><div class="decision-banner"><small>RECOMMENDATION</small><h3>${esc(c.decisionReview?.decision||t.decision)}</h3><p>${esc(c.decisionReview?.note||t.reason)}</p><div class="meta"><span class="tag good">Transferability ${t.score}%</span>${t.related?`<span class="tag">Compared with ${esc(t.related.id)}</span>`:''}${c.decisionReview?'<span class="tag good">Government reviewed</span>':''}</div></div>${decisionReview}<div class="root-list section">${t.adaptations.map(x=>`<div class="root-item"><i></i><span>${esc(x)}</span></div>`).join('')}</div></section></div>
 <div class="grid two section"><section class="card"><div class="card-head"><div><h3>Root-cause hypotheses</h3><p>Reviewable — not asserted as ground truth.</p></div></div><div class="root-list">${(c.reviewedRootCauses||c.rootCauses||[]).map(x=>`<div class="root-item"><i></i><span>${esc(x)}</span></div>`).join('')}</div>${rootReview}</section><section class="card"><div class="card-head"><div><h3>Problem family</h3><p>${family.length} related challenge${family.length===1?'':'s'} found.</p></div></div><div class="family-tree"><div class="family-root">${esc(c.id)}</div><div class="family-line"></div><div class="family-children">${family.length?family.map(x=>`<span class="family-child">${esc(x.id)} • ${esc(x.district)}</span>`).join(''):'<span class="muted modal-copy">No family relation yet</span>'}</div></div></section></div>
 <div class="grid two section"><section class="card"><div class="card-head"><div><h3>Evidence & live context</h3><p>Citizen evidence, GPS and external context stay attached to this record.</p></div></div>${(c.evidence||[]).length?`<div class="list">${c.evidence.map(f=>`<div class="list-row"><div><h4>${esc(f.name)}</h4><p>${Math.round(num(f.size)/1024)} KB • ${esc(f.type)}</p></div>${f.url?`<a class="btn sm" href="${esc(f.url)}" target="_blank">Open</a>`:''}</div>`).join('')}</div>`:'<div class="muted modal-copy">No uploaded evidence.</div>'}${ctx.address?`<div class="context-record"><span>${icon('map','sm')}</span><div><b>${esc(ctx.address)}</b><small>${ctx.weather?`Captured live context: ${ctx.weather.temperature_2m??'—'}${ctx.weatherUnits?.temperature_2m||'°C'} · precipitation ${ctx.weather.precipitation??'—'}${ctx.weatherUnits?.precipitation||' mm'}`:'Reverse-geocoded from captured GPS'}</small></div></div>`:''}${c.latitude?`<div class="dna-item map-record"><small>Captured GPS</small><b>${c.latitude.toFixed(5)}, ${c.longitude.toFixed(5)}</b>${!state.settings.lowBandwidth?`<div class="embedded-map"><iframe title="Challenge location map" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://www.openstreetmap.org/export/embed.html?bbox=${c.longitude-0.012}%2C${c.latitude-0.008}%2C${c.longitude+0.012}%2C${c.latitude+0.008}&layer=mapnik&marker=${c.latitude}%2C${c.longitude}"></iframe><a class="btn sm" target="_blank" rel="noopener" href="https://www.openstreetmap.org/?mlat=${c.latitude}&mlon=${c.longitude}#map=16/${c.latitude}/${c.longitude}">Open full map</a></div>`:''}</div>`:''}</section>
 <section class="card"><div class="card-head"><div><h3>Stakeholder comments</h3><p>Shared communication stays attached to the challenge.</p></div></div>${comments.length?comments.map(x=>`<div class="comment"><header><b>${esc(x.author)}</b><span class="tag">${esc(x.role)}</span><small>${fmtDate(x.createdAt)}</small></header><p>${esc(x.text)}</p></div>`).join(''):'<div class="muted modal-copy">No comments yet.</div>'}<form id="comment-form" data-cid="${c.id}" class="section"><div class="field"><label>Add comment</label><textarea name="comment" required></textarea></div><button class="btn">${icon('message','sm')} Add comment</button></form></section></div>
 ${session.role==='citizen'&&c.createdBy===session.id&&['submitted','under-review'].includes(c.status)?`<details class="card section citizen-edit"><summary><span>${icon('edit','sm')} Edit submitted challenge</span><small>Available until government validation</small></summary><form id="challenge-edit-form" data-cid="${c.id}" class="section"><div class="form-grid"><div class="field span-2"><label>Challenge title</label><input name="title" required value="${esc(c.title)}"/></div><div class="field span-2"><label>Problem description</label><textarea name="description" required>${esc(c.description)}</textarea></div><div class="field"><label>District</label><input name="district" required value="${esc(c.district)}"/></div><div class="field"><label>Affected population</label><input name="affectedPopulation" type="number" min="0" value="${num(c.affectedPopulation)}"/></div><div class="field"><label>Severity (1–5)</label><input name="severity" type="number" min="1" max="5" value="${num(c.severity)}"/></div><div class="field"><label>Urgency (1–5)</label><input name="urgency" type="number" min="1" max="5" value="${num(c.urgency)}"/></div></div><div class="modal-actions"><button class="btn primary">Save changes</button></div></form></details>`:''}
 ${c.proposal?`<section class="card section"><div class="card-head"><div><h3>Proposal & pre-mortem</h3><p>${esc(c.proposal.summary)} • ₹${num(c.proposal.estimatedCost).toLocaleString('en-IN')} • ${num(c.proposal.timelineWeeks)} weeks</p></div><span class="tag ${c.proposalReview==='approved'?'good':'warn'}">${c.proposalReview||'Awaiting review'}</span></div>${(c.proposal.preMortem||[]).map(x=>`<div class="premortem-row"><header><b>${esc(x.title)}</b><span class="tag ${x.probability==='High'?'bad':'warn'}">${x.probability}</span></header><p>${esc(x.mitigation)}</p></div>`).join('')}${session.role==='government'&&c.proposalReview!=='approved'?`<div class="modal-actions"><button class="btn" data-request-changes="${c.id}">Request changes</button><button class="btn primary" data-approve-proposal="${c.id}">Approve proposal</button></div>`:''}</section>`:''}
 </div></div></div>`
}
function openModal(type){clearChallengeModalLayer();if(type==='challenge'){const c=challengeById(ui.selectedChallenge);if(c){document.body.classList.add('challenge-modal-open');document.body.insertAdjacentHTML('beforeend',renderChallengeModal(c));wireModal()}}}
function closeModal(){ui.modal=null;clearChallengeModalLayer()}
