 const back=$('#modal-backdrop');back?.addEventListener('click',e=>{if(e.target===back)closeModal()});$('#modal-close')?.addEventListener('click',closeModal)
 $('#comment-form')?.addEventListener('submit',e=>{e.preventDefault();const c=challengeById(e.currentTarget.dataset.cid),txt=new FormData(e.currentTarget).get('comment');c.comments=c.comments||[];c.comments.push({id:uid('com'),author:session.name,role:session.role,text:String(txt).trim(),createdAt:now()});activity(session.name,'Added stakeholder comment',c.id);saveState('comment');closeModal();render();toast('Comment added')})
 $('#classification-correction-form')?.addEventListener('submit',async e=>{e.preventDefault();const c=challengeById(e.currentTarget.dataset.cid),d=new FormData(e.currentTarget),label=String(d.get('domain'));if(!c||label===c.domain){toast('Classification is already set to this domain');return}const previous=c.domain;c.domain=label;c.subDomain=subDomain(label,c.description);c.requiredSkills=SKILLS[label]||[];c.aiSummary=summarize(c);c.rootCauses=rootCauses(c);c.classificationSource='government-reviewed';c.classificationConfidence=1;c.classificationCorrectedFrom=previous;c.updatedAt=now();await submitMLFeedback(`${c.title} ${c.description}`,label,c.id);activity(session.name,`Corrected classification from ${previous} to ${label}`,c.id);saveState('ml-correction');closeModal();render();toast('Domain corrected. The local classifier learned from this reviewer feedback.')})
 $('#root-cause-review-form')?.addEventListener('submit',e=>{e.preventDefault();const c=challengeById(e.currentTarget.dataset.cid),d=new FormData(e.currentTarget),items=lines(d.get('rootCauses'));if(!c||!items.length){toast('Keep at least one reviewed root-cause hypothesis','error');return}c.reviewedRootCauses=items;c.rootCauseReviewStatus='reviewed';c.rootCauseRecords=items.map((hypothesis,i)=>({...(c.rootCauseRecords?.[i]||{}),id:c.rootCauseRecords?.[i]?.id||`rc_${c.id}_${i+1}`,hypothesis,reviewStatus:'approved-edited',reviewerId:session.id,reviewedAt:now(),source:c.rootCauseRecords?.[i]?.source||'reviewer'}));c.challengeDNA=buildChallengeDNA(c);c.challengeDNA.reviewStatus='reviewed';c.challengeDNA.reviewedBy=session.id;c.challengeDNA.reviewedAt=now();c.updatedAt=now();activity(session.name,'Reviewed and edited root-cause hypotheses',c.id);saveState('root-cause-review');closeModal();render();toast('Root-cause review saved')})
