 $('#challenge-edit-form')?.addEventListener('submit',async e=>{e.preventDefault();const c=challengeById(e.currentTarget.dataset.cid);if(!c||c.createdBy!==session.id||!['submitted','under-review'].includes(c.status))return;const d=new FormData(e.currentTarget);c.title=String(d.get('title')).trim();c.description=String(d.get('description')).trim();c.district=String(d.get('district')).trim();c.affectedPopulation=num(d.get('affectedPopulation'));c.severity=clamp(num(d.get('severity')),1,5);c.urgency=clamp(num(d.get('urgency')),1,5);const cls=await classifyRemote(`${c.title} ${c.description}`,'Auto-detect');c.domain=cls.domain;c.subDomain=subDomain(c.domain,c.description);c.classificationConfidence=cls.confidence;c.classificationAlternatives=cls.top||[];c.classificationSource=cls.source;c.classificationTrainingExamples=cls.trainingExamples||0;c.classificationFeedbackExamples=cls.feedbackExamples||0;c.priorityScore=priorityScore(c.severity,c.urgency,c.affectedPopulation);c.requiredSkills=SKILLS[c.domain]||[];c.aiSummary=summarize(c);c.rootCauses=rootCauses(c);c.challengeDNA=buildChallengeDNA(c);c.rootCauseRecords=buildRootCauseRecords(c);c.problemFamily=buildProblemFamily(c,duplicateFor(c,c.id));c.transferabilityAnalysis=transferDecision(c);c.intelligenceProvenance={generatedAt:now(),logicVersion:'v22-local-intelligence-1',classifierSource:c.classificationSource,humanReviewRequired:true};c.updatedAt=now();activity(session.name,'Edited submitted challenge and refreshed trained intelligence',c.id);saveState('edit-challenge');closeModal();render();toast('Challenge updated and intelligence refreshed')})
