 $$('[data-enter-pilot]').forEach(b=>b.onclick=()=>{const c=challengeById(b.dataset.enterPilot);setChallenge(c.id,{status:'pilot'},'Moved project into pilot');notifyRolesFor('pilot',c);render();toast('Project moved to pilot')});
